_LOG_TABLE = np.log(_TABLE)


def evaluate_collrad_h0_ionization_rate(electron_density_m3, electron_temperature_ev):
    """Return the COLLRAD H0 electron-impact ionization rate in m^3/s.

    Parameters
    ----------
    electron_density_m3
        Electron densities in ``m^-3``, scalar or array; must be finite and
        strictly positive.
    electron_temperature_ev
        Electron temperatures in eV, scalar or array with the same shape;
        must be finite and strictly positive.

    Returns
    -------
    numpy.ndarray
        Rate coefficients in ``m^3/s`` with the inputs' shape.  Finite and
        strictly positive for every accepted input, because the interpolation
        weights lie in ``[0, 1]`` and the frozen table entries are positive.
        Values outside the table's density and temperature ranges clamp to the
        table endpoints, the saved source's declared behavior.

    Raises
    ------
    ValueError
        If the two inputs differ in shape, contain a non-finite or
        non-positive value, or if the derived table coordinates decrease along
        the flat C-order sample sequence.
    """
    density = np.asarray(electron_density_m3, dtype=float)
    temperature = np.asarray(electron_temperature_ev, dtype=float)
    if density.shape != temperature.shape:
        raise ValueError("electron_density_m3 and electron_temperature_ev must have the same shape")
    density_flat = density.reshape(-1)
    temperature_flat = temperature.reshape(-1)
    if np.any(~np.isfinite(density_flat)) or np.any(~np.isfinite(temperature_flat)):
        raise ValueError("electron_density_m3 and electron_temperature_ev must be finite")
    if np.any(density_flat <= 0.0) or np.any(temperature_flat <= 0.0):
        raise ValueError("electron_density_m3 and electron_temperature_ev must be positive")

    density_index = np.clip(2.0 * (np.log10(density_flat / 1.0e6) - 10.0), 0.0, 14.0)
    temperature_index = np.clip(10.0 * (np.log10(temperature_flat) + 1.2), 0.0, 59.0)
    if density_flat.size > 1 and (
        np.any(np.diff(density_index) < 0.0) or np.any(np.diff(temperature_index) < 0.0)
    ):
        raise ValueError("paired density and temperature coordinates must be nondecreasing")
    density_lo = np.floor(density_index).astype(int)
    temperature_lo = np.floor(temperature_index).astype(int)
    density_hi = np.minimum(density_lo + 1, 14)
    temperature_hi = np.minimum(temperature_lo + 1, 59)
    density_fraction = density_index - density_lo
    temperature_fraction = temperature_index - temperature_lo
    q00 = _LOG_TABLE[density_lo, temperature_lo]
    q01 = _LOG_TABLE[density_lo, temperature_hi]
    q10 = _LOG_TABLE[density_hi, temperature_lo]
    q11 = _LOG_TABLE[density_hi, temperature_hi]
    row0 = q00 + temperature_fraction * (q01 - q00)
    row1 = q10 + temperature_fraction * (q11 - q10)
    flat_rate = np.exp(row0 + density_fraction * (row1 - row0))
    return flat_rate.reshape(density.shape)
